import{_ as t,c as o,o as d,ag as r}from"./chunks/framework.Ci10AEOF.js";const g=JSON.parse('{"title":"JavaScript Editor","description":"The built-in code editor features and shortcuts","frontmatter":{"title":"JavaScript Editor","description":"The built-in code editor features and shortcuts"},"headers":[],"relativePath":"engine/javascript_editor.md","filePath":"engine/javascript_editor.md","lastUpdated":1793057853000}'),a={name:"engine/javascript_editor.md"};function n(i,e,s,c,l,p){return d(),o("div",null,e[0]||(e[0]=[r('<h1 id="javascript-editor" tabindex="-1">JavaScript Editor <a class="header-anchor" href="#javascript-editor" aria-label="Permalink to &quot;JavaScript Editor&quot;">​</a></h1><p>The JavaScript Editor is the desktop Administrator&#39;s code editor for filter rules, transformer steps, channel scripts, and code templates.</p><div class="tip custom-block"><p class="custom-block-title">The Web Administrator&#39;s script editor</p><p>The <a href="./web_administrator.html">Web Administrator</a> edits scripts in the Monaco editor. It completes object members as you type, offers the channel&#39;s own code template functions as completions, and is bundled with the web client, so it works without internet access. For writing scripts it is a far better experience than the desktop editor this page describes.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="syntax-highlighting" tabindex="-1">Syntax highlighting <a class="header-anchor" href="#syntax-highlighting" aria-label="Permalink to &quot;Syntax highlighting&quot;">​</a></h3><p>The editor provides color-coded syntax highlighting for JavaScript, including OIE-specific keywords and variables such as <code>msg</code>, <code>tmp</code>, <code>connectorMap</code>, <code>channelMap</code>, <code>logger</code>, <code>FileUtil</code>, <code>DateUtil</code>, and map shorthand functions (<code>$c</code>, <code>$g</code>, <code>$s</code>, <code>$r</code>, etc.).</p><h3 id="auto-completion" tabindex="-1">Auto-completion <a class="header-anchor" href="#auto-completion" aria-label="Permalink to &quot;Auto-completion&quot;">​</a></h3><p>Press <code>Ctrl+Space</code> to open the auto-completion popup. It provides suggestions for:</p><ul><li>Built-in JavaScript functions and objects</li><li>OIE utility classes and methods (<code>ChannelUtil</code>, <code>DateUtil</code>, <code>FileUtil</code>, <code>DatabaseConnectionFactory</code>, <code>SMTPConnectionFactory</code>, etc.)</li><li>Variable map methods (<code>channelMap.put</code>, <code>globalMap.get</code>, etc.)</li><li>Code template functions available in the current context</li></ul><p>Auto-completion can also be triggered automatically after typing certain characters (<code>.</code> by default). These settings are configurable under Code Editor Preferences.</p><h3 id="find-and-replace" tabindex="-1">Find and replace <a class="header-anchor" href="#find-and-replace" aria-label="Permalink to &quot;Find and replace&quot;">​</a></h3><p><code>Ctrl+F</code> (<code>Cmd+F</code> on macOS) opens the Find / Replace dialog:</p><ul><li><strong>Find text</strong> / <strong>Replace with</strong>: Search and replace fields with history dropdowns</li><li><strong>Direction</strong>: Forward or Backward</li><li><strong>Wrap Search</strong>: Search wraps around the end of the file</li><li><strong>Match Case</strong>: Toggle case sensitivity</li><li><strong>Regular Expression</strong>: Use regular expressions for search patterns</li><li><strong>Whole Word</strong>: Match whole words only</li></ul><h3 id="code-folding" tabindex="-1">Code folding <a class="header-anchor" href="#code-folding" aria-label="Permalink to &quot;Code folding&quot;">​</a></h3><p>Collapse and expand code blocks:</p><ul><li>Click the fold icons in the gutter (left margin)</li><li>Collapse functions, if/else blocks, loops, and other block structures</li><li>Use the Folding submenu in the context menu or keyboard shortcuts to collapse/expand folds</li></ul><h2 id="context-menu" tabindex="-1">Context menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to &quot;Context menu&quot;">​</a></h2><p>Right-click in the editor to access:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Undo / Redo</strong></td><td>Undo/redo recent changes</td></tr><tr><td><strong>Cut / Copy / Paste / Delete</strong></td><td>Standard clipboard operations</td></tr><tr><td><strong>Select All</strong></td><td>Select all code in the editor</td></tr><tr><td><strong>Find/Replace</strong></td><td>Open the find/replace dialog</td></tr><tr><td><strong>Find Next</strong></td><td>Find the next occurrence</td></tr><tr><td><strong>Clear Marked Occurrences</strong></td><td>Clear highlighted search results</td></tr><tr><td><strong>Folding</strong></td><td>Submenu: Collapse Current Fold, Expand Current Fold, Collapse All Folds, Collapse Comment Folds, Expand All Folds</td></tr><tr><td><strong>Display</strong></td><td>Submenu: Show Tab Lines, Show Whitespace, Show Line Endings, Wrap Lines</td></tr><tr><td><strong>Code</strong></td><td>Submenu: Format, Toggle Comment</td></tr><tr><td><strong>Macro</strong></td><td>Submenu: Begin Recording Macro, End Recording Macro, Playback Recorded Macro</td></tr><tr><td><strong>View User API</strong></td><td>Open the User API documentation</td></tr></tbody></table><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Default shortcuts. On macOS most of them use Cmd where Windows and Linux use Ctrl:</p><table tabindex="0"><thead><tr><th>Windows and Linux</th><th>macOS</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Space</code></td><td><code>Ctrl+Space</code></td><td>Open auto-completion popup</td></tr><tr><td><code>Ctrl+F</code></td><td><code>Cmd+F</code></td><td>Find and Replace</td></tr><tr><td><code>Ctrl+G</code></td><td><code>Cmd+G</code></td><td>Find Next</td></tr><tr><td><code>Ctrl+Z</code></td><td><code>Cmd+Z</code></td><td>Undo</td></tr><tr><td><code>Ctrl+Y</code></td><td><code>Cmd+Shift+Z</code></td><td>Redo</td></tr><tr><td><code>Ctrl+/</code></td><td><code>Cmd+/</code></td><td>Toggle line comment</td></tr><tr><td><code>Ctrl+Shift+F</code></td><td><code>Ctrl+Shift+F</code></td><td>Format code</td></tr><tr><td><code>Ctrl+D</code></td><td><code>Cmd+D</code></td><td>Delete line</td></tr><tr><td><code>Ctrl+J</code></td><td><code>Cmd+J</code></td><td>Join lines</td></tr><tr><td><code>Ctrl+[</code></td><td><code>Cmd+[</code></td><td>Go to matching bracket</td></tr><tr><td><code>Ctrl+A</code></td><td><code>Cmd+A</code></td><td>Select all</td></tr><tr><td><code>Ctrl</code> + numeric keypad minus</td><td><code>Cmd</code> + numeric keypad minus</td><td>Collapse current fold</td></tr><tr><td><code>Ctrl</code> + numeric keypad plus</td><td><code>Cmd</code> + numeric keypad plus</td><td>Expand current fold</td></tr><tr><td><code>Ctrl</code> + numeric keypad divide</td><td><code>Cmd</code> + numeric keypad divide</td><td>Collapse all folds</td></tr><tr><td><code>Ctrl+Shift</code> + numeric keypad divide</td><td><code>Cmd+Shift</code> + numeric keypad divide</td><td>Collapse comment folds</td></tr><tr><td><code>Ctrl</code> + numeric keypad multiply</td><td><code>Cmd</code> + numeric keypad multiply</td><td>Expand all folds</td></tr><tr><td><code>Tab</code></td><td><code>Tab</code></td><td>Indent selected lines</td></tr><tr><td><code>Shift+Tab</code></td><td><code>Shift+Tab</code></td><td>Unindent selected lines</td></tr></tbody></table><p>The fold shortcuts use the keys on the numeric keypad, not the minus and plus keys on the main keyboard, so a keyboard without a numeric keypad needs them remapped. Every shortcut above except <code>Tab</code> and <code>Shift+Tab</code> can be remapped under <strong>Settings &gt; Administrator &gt; Code Editor Preferences</strong> using the Shortcut Key Mappings table.</p><h2 id="reference-list" tabindex="-1">Reference list <a class="header-anchor" href="#reference-list" aria-label="Permalink to &quot;Reference list&quot;">​</a></h2><p>The <strong>Reference List</strong> panel sits next to the script editor and lists functions, code snippets, and variables by category. Use the <strong>Category</strong> dropdown to filter by category and the <strong>Filter</strong> field to search within the selected category.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>The <strong>Category</strong> dropdown starts on <strong>All</strong>. A category appears only when it has items for the script you are editing, and <strong>User Defined Code</strong> and <strong>User Defined Functions</strong> appear only when code templates of that type apply to the current script.</p><p>The categories, with examples of what each holds:</p><ul><li><strong>Conversion Functions</strong>: Get Serializer, Convert XML to JSON, Convert JSON to XML</li><li><strong>Logging and Alerts</strong>: log an info or error statement, send an email, trigger an alert</li><li><strong>Database Functions</strong>: database queries and updates, and the connection template and driver name for each bundled driver</li><li><strong>Utility Functions</strong>: reading and writing files, Base64, routing to another channel, attachments, hashing, DICOM images, pretty printing XML and JSON</li><li><strong>Date Functions</strong>: parsing, formatting and converting dates, and getting the current date</li><li><strong>Message Functions</strong>: the incoming message, raw or transformed, its type, version and IDs, iterating over and deleting segments, and removing destinations from the destination set</li><li><strong>Response Transformer</strong>: setting the response status to SENT, QUEUED or ERROR, and its status message and error message</li><li><strong>Map Functions</strong>: getting and putting values in each map, looking a key up in all maps, and creating a sent or error response</li><li><strong>Channel Functions</strong>: the channel ID and name</li><li><strong>Postprocessor Functions</strong>: the completed message and its merged, source and destination connector messages</li><li><strong>User Defined Code</strong>: User-created code templates (code type)</li><li><strong>User Defined Functions</strong>: User-created code templates (function type)</li></ul><p>Rest the pointer on an item to see its description, then drag it into the editor to insert the code.</p><h3 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h3><p>Which variables appear depends on the current script context. Examples include:</p><ul><li><code>msg</code> (inbound message in filter/transformer scripts), <code>tmp</code> (outbound template in filter/transformer scripts)</li><li><code>connectorMessage</code> (in connector scripts)</li><li><code>message</code> (completed message object in the postprocessor)</li><li><code>response</code>, <code>responseStatus</code>, <code>responseErrorMessage</code>, <code>responseStatusMessage</code> (in response transformer scripts)</li><li>Map objects: <code>connectorMap</code>, <code>channelMap</code>, <code>sourceMap</code>, <code>globalChannelMap</code>, <code>globalMap</code>, <code>configurationMap</code>, <code>responseMap</code></li><li><code>logger</code>, <code>router</code>, <code>alerts</code>, <code>replacer</code>, <code>contextFactory</code></li></ul><h2 id="code-editor-preferences" tabindex="-1">Code editor preferences <a class="header-anchor" href="#code-editor-preferences" aria-label="Permalink to &quot;Code editor preferences&quot;">​</a></h2><p>Configure editor behavior in <strong>Settings &gt; Administrator &gt; Code Editor Preferences</strong>:</p><table tabindex="0"><thead><tr><th>Preference</th><th>Description</th></tr></thead><tbody><tr><td><strong>Auto-Complete Characters</strong></td><td>Characters that trigger the auto-completion popup (default: <code>.</code>)</td></tr><tr><td><strong>Include Letters</strong></td><td>If enabled, auto-completion triggers after any letter is typed</td></tr><tr><td><strong>Activation Delay (ms)</strong></td><td>Time to wait after typing a trigger character before showing the popup (default: 300 ms)</td></tr><tr><td><strong>Shortcut Key Mappings</strong></td><td>Table of all remappable editor actions with their current keyboard shortcuts; double-click a shortcut to change it</td></tr><tr><td><strong>Restore Defaults</strong></td><td>Reset all shortcut key mappings to their defaults</td></tr></tbody></table>',36)]))}const u=t(a,[["render",n]]);export{g as __pageData,u as default};
